function Is_Error_Signaling_Statement (N : Node_Id) return Boolean is
begin
   case Nkind (N) is
      when N_Raise_xxx_Error | N_Raise_Expression =>
         return True;

      --  Only unhandled exceptions are considered to signal errors

      when N_Raise_Statement                      =>
         return not Might_Raise_Handled_Exceptions (N);

      when N_Pragma                               =>
         if Is_Pragma_Check (N, Name_Assert) then
            declare
               Arg1 : constant Node_Id :=
                 First (Pragma_Argument_Associations (N));
               Arg2 : constant Node_Id := Next (Arg1);
               Expr : constant Node_Id := Expression (Arg2);
            begin
               return
                 Compile_Time_Known_Value (Expr)
                 and then Is_False (Expr_Value (Expr));
            end;
         else
            return False;
         end if;

      --  Recognize calls to functions with a precondition of False

      when N_Function_Call                        =>
         declare
            Subp     : constant Entity_Id := Get_Called_Entity (N);
            Pre_List : constant Node_Lists.List :=
              Find_Contracts (Subp, Pragma_Precondition);
            use type Ada.Containers.Count_Type;
         begin
            return
              Pre_List.Length = 1
              and then
                (declare
                   Expr : constant N_Subexpr_Id := Pre_List.First_Element;
                 begin
                   Nkind (Expr) in N_Expanded_Name | N_Identifier
                   and then Entity (Expr) = Standard_False);
         end;

      when others                                 =>
         return False;
   end case;
end Is_Error_Signaling_Statement;

procedure Collect_Vertices_Leading_To
  (Graph       : Graph_Id;
   Targets     : in out Vertex_Sets.Set;
   Pred        : not null access function (V : Vertex) return Boolean :=
     True_On_Every_Vertex'Access;
   Empty_Paths : Boolean := True)
is
   Exploration_Set : Vertex_Sets.Set := Vertex_Sets.Empty_Set;
   --  Stores vertices that remain to be explored

   Initial_Set : constant Vertex_Sets.Set := Targets;
   --  Copy Targets input value so that we can immediately use Targets
   --  as accumulator (needed when Empty_Paths = False).

   procedure Add_Predecessors (V : Vertex);
   --  Add Pred-satisfying predecessors of N to exploration set,
   --  excluding those already in Targets.

   ----------------------
   -- Add_Predecessors --
   ----------------------

   procedure Add_Predecessors (V : Vertex) is
   begin
      for V_Pred of Predecessors (Graph, V) loop
         if not Targets.Contains (V_Pred) and then Pred (V_Pred) then
            Exploration_Set.Include (V_Pred);
         end if;
      end loop;
   end Add_Predecessors;

   --  Start of processing for Collect_Vertices_Leading_To

begin
   if not Empty_Paths then
      Targets.Clear;
   end if;
   for T of Initial_Set loop
      Add_Predecessors (T);
   end loop;
   while not Exploration_Set.Is_Empty loop
      declare
         V_Pos : Vertex_Sets.Cursor := Exploration_Set.First;
         V_Top : constant Vertex := Exploration_Set.Element (V_Pos);
      begin
         Exploration_Set.Delete (V_Pos);
         Targets.Insert (V_Top);
         Add_Predecessors (V_Top);
      end;
   end loop;
end Collect_Vertices_Leading_To;

begin
   --  Add neighborhood of start vertex to the table

   Insert_Neighborhood (Start, Depth);

   if Is_Error_Signaling_Statement (Stmt) then
      --  If the statement is an error signaling one,
      --  then we will never reach any meaningful exit path
      --  from it, so no edge needs to be added to the graph.

      pragma Assert (Start.Kind = Entrance);
      goto Finish;
   end if;

   case Nkind (Stmt) is
      when N_Block_Statement                       =>
         Exit_Temp := Vertex'(Kind => Completion, Node => Stmt);

when N_If_Statement                          =>

   declare
      Elsif_Iter : Node_Id := First (Elsif_Parts (Stmt));
   begin
      --  Like case statements, create one path per alternative.

      Exit_Temp := Exit_Vertex;
      Cache_For_Statement_List
        (Then_Statements (Stmt), Depth + 1, Exit_Temp);
      Add_Edge (Start, Exit_Temp);
      Exit_Temp := Exit_Vertex;
      Cache_For_Statement_List
        (Else_Statements (Stmt), Depth + 1, Exit_Temp);
      Add_Edge (Start, Exit_Temp);
      while Present (Elsif_Iter) loop
         Exit_Temp := Exit_Vertex;
         Cache_For_Statement_List
           (Then_Statements (Elsif_Iter), Depth + 1, Exit_Temp);
         Add_Edge (Start, Exit_Temp);
         Next (Elsif_Iter);
      end loop;
   end;

when N_Loop_Statement                        =>
   declare
      Loop_Entity : constant Node_Id :=
        Entity (Identifier (Stmt));
      Vertex_Cond : constant Vertex :=
        Vertex'(Kind => Loop_Cond, Node => Stmt);
      Vertex_Iter : constant Vertex :=
        Vertex'(Kind => Loop_Iter, Node => Stmt);
   begin

      --  Register target for inner exit statements.

      Loop_Exit_Nodes.Insert (Loop_Entity, Exit_Vertex);

      --  Insert extra vertices.

      Insert_Neighborhood (Vertex_Cond, Depth + 1);
      Insert_Neighborhood (Vertex_Iter, Depth + 1);
      Add_Edge (Start, Vertex_Cond);
      Add_Edge (Vertex_Iter, Vertex_Cond);

      if Present (Iteration_Scheme (Stmt)) then
         --  Normal loop exit.
         --  Cannot directly exit simple loops.

         Add_Edge (Vertex_Cond, Exit_Vertex);
      end if;

      --  End of the loop performs the iteration and goes back
      --  to condition.

      Exit_Temp := Vertex_Iter;
      Cache_For_Statement_List
        (Statements (Stmt), Depth + 1, Exit_Temp);

      --  Condition may enter the loop

      Add_Edge (Vertex_Cond, Exit_Temp);
   end;

function Predecessors (G : Graph_Id; V : Vertex) return Vertex_Sets.Set
is
   function Depth (Neighbor : Vertex) return Natural
   is (All_Graphs.Constant_Reference (Neighbor).Depth_In_Enclosing);
   --  Short-hand to fetch vertex depth.

begin
   Cache_Graph_If_Needed (G);
   return Preds : Vertex_Sets.Set := Vertex_Sets.Empty_Set do
      declare
         Graph_Start : constant Vertex := Starting_Vertex (G);
         Depth_Limit : constant Natural := Depth (Graph_Start);

         function In_Local_CFG (Neighbor : Vertex) return Boolean
         is (declare
               Neigh_Depth : constant Natural := Depth (Neighbor);
             begin
               Neigh_Depth > Depth_Limit
               or else
                 (Neigh_Depth = Depth_Limit
                  and then Neighbor = Graph_Start));
         --  Test if vertex Neighbor is within G's CFG.
         --  This only works correctly for vertices of G's CFG
         --  and their neighbors, for other vertices in the graph,
         --  there can be false positives.

      begin
         --  Must hold if V is in G's CFG.

         pragma Assert (In_Local_CFG (V));

         for Neighbor of
           All_Graphs.Constant_Reference (V).Ctrl_Predecessors
         loop
            if In_Local_CFG (Neighbor) then
               Preds.Insert (Neighbor);
            end if;
         end loop;
      end;
   end return;

procedure Get_Loop_Writes
  (Loop_Stmt       : N_Loop_Statement_Id;
   Loop_Writes     : out Write_Status_Maps.Map;
   Invalid_Objects : out Node_Sets.Set)
is
   Stmts     : constant List_Id := Statements (Loop_Stmt);
   Scheme    : constant Opt_N_Iteration_Scheme_Id :=
     Iteration_Scheme (Loop_Stmt);
   After_Inv : Boolean := True;
   --  Only try to keep variables declared inside the loop as completely
   --  written instead of discarded if there is a loop invariant (and this
   --  will only impact variables declared before the loop invariant).
   --  Otherwise, there is no meaningful use for these variables in the
   --  frame condition.

   Flat_Body : constant Node_Lists.List :=
     Get_Flat_Statement_And_Declaration_List (Stmts);
   --  Flattened loop body.

   Relevant_Vertices : Local_CFG.Vertex_Sets.Set;
   --  To store vertices of loop's local CFG that can lead back to
   --  invariant. This let us detect which writes can actually happen
   --  before the invariant is reached (again). Other writes are
   --  not actually relevant modifications of variables
   --  for computing the frame condition.

begin
   --  The loop index is completely written

   if Present (Scheme) and then No (Condition (Scheme)) then
      declare
         Loop_Param_Ent : E_Loop_Parameter_Id;
      begin
         if Present (Loop_Parameter_Specification (Scheme)) then
            Loop_Param_Ent :=
              Defining_Identifier (Loop_Parameter_Specification (Scheme));
         else
            pragma Assert (Present (Iterator_Specification (Scheme)));
            Loop_Param_Ent :=
              Defining_Identifier (Iterator_Specification (Scheme));
         end if;

         --  For the loop index of the top-level loop, consider the variable
         --  as completely written instead of discarded, as this allows
         --  stating the dynamic property of the loop index in the frame
         --  condition.

         Write_Entity
           (New_Write      => Loop_Param_Ent,
            Loop_Writes    => Loop_Writes,
            Discard_Writes => After_Inv,
            Relevant_Path  => True);

      end;
   end if;

   --  Find relevant vertices.
   declare
      Inv_Vertex : Local_CFG.Vertex;
   begin
      for N_Iter of reverse Flat_Body loop
         if Is_Pragma_Check (N_Iter, Name_Loop_Invariant)
           or else Is_Pragma (N_Iter, Pragma_Loop_Variant)
         then
            Inv_Vertex := Local_CFG.Starting_Vertex (N_Iter);
            goto Found;
         end if;
      end loop;
      Inv_Vertex :=
        Local_CFG.Vertex'(Kind => Local_CFG.Loop_Cond, Node => Loop_Stmt);
      <<Found>>
      Relevant_Vertices.Insert (Inv_Vertex);
      Local_CFG.Collect_Vertices_Leading_To (Loop_Stmt, Relevant_Vertices);
   end;

   begin
      if not Is_Constant_In_SPARK (Formal)
        and then
          (Ekind (Formal) /= E_In_Parameter
           or else Nkind (Actual) /= N_Null)
      then
         --  If Formal is an IN parameter of an access-to-variable type, the
         --  designated value only can be updated by the call, not the
         --  access itself.

         Write_Expr
           (Actual,
            Loop_Writes,
            After_Inv,
            Relevant_Path,
            Deref_Only =>
              Ekind (Formal) = E_In_Parameter
              and then Has_Access_Type (Etype (Formal)));

         --  If the validity flag of the formal is transfered to the actual,
         --  add the root object to Invalid_Objects.

         if Propagates_Validity_Flag (Actual) then
            Invalid_Objects.Include
              (Unique_Entity (Get_Root_Object (Actual)));
         end if;
      end if;
   end Process_Param;

   procedure Store_Parameters is new
     Iterate_Call_Parameters (Process_Param);

   Subp : constant Callable_Kind_Id := Get_Called_Entity_For_Proof (Call);

   --  Start of processing for Process_Call_Statement

begin
   --  Record writes to out and in out parameters of the call

   Store_Parameters (Call);

   --  Record writes to the global out and in out of Subp

   declare
      Read_Ids  : Flow_Types.Flow_Id_Sets.Set;
      Write_Ids : Flow_Types.Flow_Id_Sets.Set;

   begin
      Flow_Utility.Get_Proof_Globals
        (Subprogram      => Subp,
         Reads           => Read_Ids,
         Writes          => Write_Ids,
         Erase_Constants => True,
         Scop            => Get_Flow_Scope (Call));

      for F of Write_Ids loop
         pragma Assert (F.Kind in Direct_Mapping | Magic_String);

         --  Magic_String are global state with no attached entities. As
         --  such state is translated as private in Why3, we do not need
         --  to assume any invariant for it.

         if F.Kind = Direct_Mapping then
            declare
               Entity : constant Entity_Id := Get_Direct_Mapping_Id (F);

            begin
               if Is_Object (Entity) and then Is_Mutable_In_Why (Entity)
               then
                  Write_Entity
                    (Entity,
                     Loop_Writes,
                     Discard_Writes => False,
                     Relevant_Path  => Relevant_Path);

                  --  If Entity has a validity flag, add it to
                  --  Invalid_Objects.

                  if Object_Has_Valid_Id (Entity) then
                     Invalid_Objects.Include (Unique_Entity (Entity));
                  end if;
               end if;
            end;
         end if;
      end loop;
   end;

procedure Write_Entity
  (New_Write      : Object_Kind_Id;
   Loop_Writes    : in out Write_Status_Maps.Map;
   Discard_Writes : Boolean;
   Relevant_Path  : Boolean) is
begin
   --  If New_Write has asynchronous writers, it is discarded so that
   --  none of its parts can be considered preserved. Protected components
   --  and Part_Of variables are not supported.

   if Discard_Writes
     or else Has_Volatile (New_Write)
     or else Is_Protected_Component_Or_Discr_Or_Part_Of (New_Write)
   then
      Discard_Entity (New_Write, Loop_Writes);
   elsif Relevant_Path then
      Write_Entity (New_Write, Loop_Writes);
   else
      Touch_Entity (New_Write, Loop_Writes);
   end if;
end Write_Entity;

----------------
-- Write_Expr --
----------------

procedure Write_Expr
  (New_Write     : N_Subexpr_Id;
   Loop_Writes   : in out Write_Status_Maps.Map;
   After_Inv     : Boolean;
   Relevant_Path : Boolean;
   Deref_Only    : Boolean := False)
is
   Root : constant Entity_Id := Get_Root_Object (New_Write);

begin
   --  If New_Write has asynchronous writers, it is discarded so that
   --  none of its parts can be considered preserved. Protected components
   --  and Part_Of variables are not supported.

   if Has_Volatile (Root)
     or else Is_Protected_Component_Or_Discr_Or_Part_Of (Root)
   then
      Discard_Entity (Root, Loop_Writes);
      return;
   end if;

   --  If the write is not on a path relevant to the frame condition,
   --  we only need to ensures that the root object is in the table,
   --  so that we remember that the object is written within the
   --  loop body.

   if not Relevant_Path then
      Touch_Expr (New_Write, Loop_Writes);
      return;
   end if;

   Write_Expr
     (New_Write  => New_Write,
      Writes     => Loop_Writes,
      Array_Data => After_Inv,
      Deref_Only => Deref_Only);
end Write_Expr;

